exhibit.text:
resource appVm 'Microsoft.Compute/virtualMachines@2024-11-01' = {
  name: 'app-vm-01'
  location: 'eastus'
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D2s_v5'
    }
  }
}

# params.json
{
  "parameters": {
    "vmSize":        { "value": "Standard_B2s" },
    "location":      { "value": "eastus" },
    "instanceCount": { "value": "2" }
  }
}

# pipeline step
az deployment group create \
  --resource-group rg-app \
  --template-file main.bicep \
  --parameters @params.json \
  --parameters vmSize=Standard_D2s_v5 \
  --parameters location=westus2 \
  --parameters location=westeurope

Template: main.bicep

param deployConditional bool = false

resource existingApp 'Microsoft.Storage/storageAccounts' = {
  name: 'stexisting001'
  location: 'eastus'
  sku: { name: 'Standard_LRS' }
  tags: { workload: 'new' }
}

resource conditionalApp 'Microsoft.Storage/storageAccounts' = if (deployConditional) {
  name: 'stconditional001'
  location: 'eastus'
  sku: { name: 'Standard_LRS' }
}

Command:
az deployment group create --resource-group rg-app --template-file main.bicep --mode Incremental

Current contents of rg-app:
- existingApp: tags: { workload: 'old' }
- conditionalApp: created by an earlier deployment
- outOfScopeApp: created by an earlier deployment and not declared in main.bicep

param monitoringEnabled bool = true

resource sa 'Microsoft.Storage/storageAccounts' = {
  name: 'stgapp001'
  location: resourceGroup().location
}

resource monitor 'Microsoft.Insights/components' = {
  condition: monitoringEnabled
  name: 'app-monitor'
  location: resourceGroup().location
}

module network './network.bicep' = {
  name: 'networkDeploy'
}

resource vnet 'Microsoft.Network/virtualNetworks@2023-05-01' = {
  name: 'vnet-app'
  location: resourceGroup().location
  properties: {
    addressSpace: {
      addressPrefixes: ['10.0.0.0/16']
    }
  }
}

resource snet 'Microsoft.Network/virtualNetworks/subnets@2023-05-01' = {
  parent: vnet
  name: 'snet-app'
  properties: {
    addressPrefix: '10.0.1.0/24'
  }
}

// main.bicep
param vmCount int = 3

resource vms 'Microsoft.Compute/virtualMachines@2024-07-01' = [for i in range(0, vmCount): {
  name: 'vm${i}'
  location: resourceGroup().location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D2s_v5'
    }
    osProfile: {
      computerName: 'vm${i}'
      adminUsername: 'azureuser'
    }
  }
}]

// pipeline step
az deployment group create \
  --resource-group rg-app \
  --template-file main.bicep \
  --mode Complete \
  --parameters vmCount=3
